// Function to get Feather SVG manually (Feather icons are very similar to Lucide)
function getFeatherSVG(iconName) {
    // Feather and Lucide are similar/same, so reuse Lucide SVG
    return getLucideSVG(iconName);
}

// Function to get HugeIcons SVG manually
function getHugeiconsSVG(iconName) {
    const baseAttrs = 'xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"';
    // Map HugeIcons names to equivalent Lucide-style SVGs
    const nameMap = {
        'add': 'plus',
        'remove': 'minus',
        'cancel': 'x',
        'delete': 'trash',
        'location': 'map-pin',
        'notification': 'bell',
        'alert': 'alert-triangle'
    };
    const mappedName = nameMap[iconName] || iconName;
    return getLucideSVG(mappedName);
}


// Function to populate the table
function populateTable() {
    const tbody = document.getElementById('comparison-tbody');
    
    iconMappings.forEach(mapping => {
        const row = document.createElement('tr');
        
        // Icon type cell
        const typeCell = document.createElement('td');
        typeCell.className = 'icon-type-cell';
        typeCell.textContent = mapping.type;
        row.appendChild(typeCell);
        
        // Library cells
        ['lucide', 'tabler', 'heroicons', 'phosphor', 'feather', 'hugeicons'].forEach(library => {
            const cell = document.createElement('td');
            cell.className = 'icon-cell';
            
            const icons = mapping[library] || [];
            
            if (icons.length === 0) {
                cell.innerHTML = '<span class="empty-cell">—</span>';
            } else {
                icons.forEach(iconName => {
                    cell.appendChild(createIcon(library, iconName));
                });
            }
            
            row.appendChild(cell);
        });
        
        tbody.appendChild(row);
    });
}

// Initialize the page
document.addEventListener('DOMContentLoaded', function() {
    populateTable();
});